import json, sys

def dumps(v): return json.dumps(v, ensure_ascii=False, separators=(',', ':'))

def to_messages(items):
    msgs = []
    def push(role, blocks=None, text=None):
        msgs.append({'role': role, 'blocks': blocks or [], 'text': text})
    for it in items:
        t, role = it.get('type'), it.get('role')
        if t == 'function_call':
            push('assistant', [{'type': 'tool_use', 'id': it['call_id'], 'name': it['name'], 'input': json.loads(it['arguments'] or '{}')}])
        elif t == 'function_call_output':
            push('user', [{'type': 'tool_result', 'tool_use_id': it['call_id'], 'content': it['output']}])
        elif t in ('reasoning',):
            push('assistant', [{'type': 'thinking', 'thinking': '', 'signature': it.get('encrypted_content', '')}])
        elif role == 'developer':
            push('system', text=it['content'] if isinstance(it['content'], str) else ''.join(p.get('text', '') for p in it['content']))
        elif role in ('user', 'assistant'):
            content = it['content']
            if isinstance(content, str):
                blocks = [{'type': 'text', 'text': content}]
            else:
                blocks = []
                for p in content:
                    if p['type'] in ('input_text', 'output_text'):
                        blocks.append({'type': 'text', 'text': p['text']})
                    elif p['type'] == 'input_image':
                        url = p['image_url']; mime, data = url[5:].split(';base64,')
                        blocks.append({'type': 'image', 'source': {'type': 'base64', 'media_type': mime, 'data': data}})
                    else:
                        blocks.append({'type': 'document', 'source': p})
            push(role, blocks)
        else:
            raise SystemExit('unknown item ' + dumps(it)[:200])
