    # followed by assistant/end becomes user text.
    changed = True
    while changed:
        changed = False
        merged = []
        for m in msgs:
            if merged and merged[-1]['role'] == m['role']:
                if m['role'] == 'system':
                    merged[-1]['text'] += '\n\n' + m['text']
                else:
                    merged[-1]['blocks'] += m['blocks']
                changed = True
                continue
            merged.append(m)
        msgs = merged
        for i, m in enumerate(msgs):
            if m['role'] != 'system':
                continue
            after_user = i > 0 and msgs[i - 1]['role'] == 'user'
            then_answer = i + 1 == len(msgs) or msgs[i + 1]['role'] == 'assistant'
            if after_user and then_answer:
                continue
            m['role'], m['blocks'], m['text'] = 'user', [{'type': 'text', 'text': m['text']}], None
            changed = True
    return [{'role': 'system', 'content': m['text']} if m['role'] == 'system' else {'role': m['role'], 'content': m['blocks']}
            for m in msgs]

def main(path):
    cases = json.load(open(path))['cases']
    total_before = 0
    rows = []
    for name, case in cases.items():
        messages = to_messages(case['body']['input'])
        last_user = max(i for i, m in enumerate(messages) if m['role'] == 'user')
        after = messages[last_user + 1:]
        after_bytes = sum(len(dumps(m).encode()) for m in after) + max(0, len(after) - 0)  # commas between messages
        skill_text = sum(len(m['content'].encode()) for m in after if m['role'] == 'system')
        kinds = ','.join(m['role'] for m in after) or '-'
        # Everything before and including the breakpoint block, for scale.
        before_bp = len(dumps(messages[:last_user + 1]).encode())
        rows.append((name, after_bytes, skill_text, kinds, before_bp))
        total_before += after_bytes
    print('| case | bytes after last breakpoint today | of which skill text | messages after it | messages up to and incl. the breakpoint |')
    print('|---|---|---|---|---|')
    for r in rows:
        print(f'| {r[0]} | {r[1]:,} | {r[2]:,} | {r[3]} | {r[4]:,} |')
    with_skill = [r for r in rows if r[1]]
    print(f'\ncases with bytes after the breakpoint: {len(with_skill)} of {len(rows)}; total {total_before:,} bytes; '
          f'max {max(r[1] for r in rows):,}')

main(sys.argv[1])
